ee:message.ee:set-payload:
%dw 2.0
output application/json
var legalName = upper(payload.legalName default "")
var directors = (payload.directors default []) map (d) -> upper(d as String)
var owners = (payload.beneficialOwners default []) map (o) -> upper(o as String)
var indicators = ["SANCTIONED","TERROR","BLACKLIST","OFAC","ISIS","ALQAEDA"]
var hitByName = indicators any ((i) -> legalName contains i)
var hitByDirector = directors any ((d) -> indicators any ((i) -> d contains i))
var hitByOwner = owners any ((o) -> indicators any ((i) -> o contains i))
var hit = hitByName or hitByDirector or hitByOwner
---
{
  status: if (isEmpty(legalName)) "INCONCLUSIVE" else if (hit) "FAIL" else "PASS",
  sanctionsHit: if (isEmpty(legalName)) false else hit,
  reasons:
    if (isEmpty(legalName)) ["Missing legalName for AML screening"]
    else if (hit) ["Potential sanctions match found in entity/owner/director names"]
    else ["No sanctions indicators detected in demo screening"],
  matchedSources: if (hit) ["ofac","eu","unsc"] else [],
  checkId: "AML-" ++ (now() as String {format: "yyyyMMddHHmmss"}),
  checkedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"},
  sourceRef: vars.correlationId
}

%dw 2.0
output application/json
---
{
  tools: [
    {
      name: "runAmlScreening",
      description: "Run AML and sanctions screening for onboarding.",
      inputSchema: {
        type: "object",
        required: ["legalName", "registrationNumber", "jurisdiction"],
        properties: {
          legalName: { type: "string" },
          registrationNumber: { type: "string" },
          jurisdiction: { type: "string" },
          beneficialOwners: { type: "array", items: { type: "string" } },
          directors: { type: "array", items: { type: "string" } },
          idempotencyKey: { type: "string" }
        }
      }
    }
  ]
}

%dw 2.0
output application/json
var req = vars.requestInput default {}
var legalName = upper(req.legalName default "")
var directors = (req.directors default []) map (d) -> upper(d as String)
var owners = (req.beneficialOwners default []) map (o) -> upper(o as String)
var indicators = ["SANCTIONED","TERROR","BLACKLIST","OFAC","ISIS","ALQAEDA"]
var hitByName = indicators any ((i) -> legalName contains i)
var hitByDirector = directors any ((d) -> indicators any ((i) -> d contains i))
var hitByOwner = owners any ((o) -> indicators any ((i) -> o contains i))
var hit = hitByName or hitByDirector or hitByOwner
---
{
  status: if (isEmpty(legalName)) "INCONCLUSIVE" else if (hit) "FAIL" else "PASS",
  sanctionsHit: if (isEmpty(legalName)) false else hit,
  reasons:
    if (isEmpty(legalName)) ["Missing legalName for AML screening"]
    else if (hit) ["Potential sanctions match found in entity/owner/director names"]
    else ["No sanctions indicators detected in demo screening"],
  matchedSources: if (hit) ["ofac","eu","unsc"] else [],
  checkId: "AML-" ++ (now() as String {format: "yyyyMMddHHmmss"}),
  checkedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"},
  sourceRef: vars.correlationId
}
